fn numpy_insert<T>(arr: Vec<T>, idx: usize, value: T) -> Vec<T> {
    assert!(idx <= arr.len());

    let mut result = Vec::with_capacity(arr.len() + 1);

    // Move elements before idx
    result.extend(arr.into_iter().take(idx));
    // Insert the new value at idx
    result.push(value);
    // Move the remaining elements (shifted right by one)
    result.extend(arr.into_iter().skip(idx));

    result
}